package pe.greenminds.ecomind.community.application.internal.commandservices;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.greenminds.ecomind.community.application.commandservices.PostCommandService;import pe.greenminds.ecomind.community.domain.model.aggregates.Post;import pe.greenminds.ecomind.community.domain.model.commands.*;import pe.greenminds.ecomind.community.domain.repositories.*;import pe.greenminds.ecomind.shared.application.result.*;
@Service public class PostCommandServiceImpl implements PostCommandService{private final PostRepository posts;private final CommunityMembershipRepository memberships;public PostCommandServiceImpl(PostRepository p,CommunityMembershipRepository m){posts=p;memberships=m;}
 @Transactional public Result<Post,ApplicationError> handle(CreatePostCommand c){if(memberships.findByCommunityIdAndUserId(c.communityId(),c.authorId()).isEmpty())return Result.failure(ApplicationError.forbidden("COMMUNITY_MEMBERSHIP_REQUIRED","Community membership is required"));try{return Result.success(posts.save(new Post(null,c.communityId(),c.authorId(),c.content(),"USER",c.imageUrl(),null)));}catch(IllegalArgumentException e){return Result.failure(ApplicationError.validationError("Post",e.getMessage()));}}
 @Transactional public Result<Void,ApplicationError> handle(DeletePostCommand c){var found=posts.findById(c.postId());if(found.isEmpty())return Result.failure(ApplicationError.notFound("Post",String.valueOf(c.postId())));if(found.get().authorId()==null||!found.get().authorId().equals(c.requestedBy()))return Result.failure(ApplicationError.forbidden("POST_DELETE_FORBIDDEN","Only the post author may delete it"));posts.delete(found.get());return Result.success(null);}}
